.filters{display:flex;gap:6px;margin:16px 0}
.filters button{flex:1;padding:8px;background:#eef1f7;color:#445}
.filters button.active{background:#4f6cf7;color:#fff}
ul{list-style:none;margin:0;padding:0}
li{display:flex;align-items:center;gap:10px;padding:10px 4px;border-bottom:1px solid #eee}
