li.done span{text-decoration:line-through;color:#999}
.del{background:none;color:#d33;font-size:18px;padding:2px 8px}
.del:hover{background:#fee}
.info{margin-top:12px;font-size:13px;color:#778;display:flex;justify-content:space-between}
.info button{background:none;color:#778;text-decoration:underline;font-size:13px}
.empty{text-align:center;color:#99a;padding:20px 0}
</style>
</head>
<body>
<div class="app">
  <h1>Todo List</h1>
  <form id="form">
    <input type="text" id="input" placeholder="What needs to be done?" autocomplete="off" autofocus>
    <button class="add" type="submit">Add</button>
  </form>
  <div class="filters" id="filters">
    <button data-f="all" class="active">All</button>
    <button data-f="active">Active</button>
    <button data-f="completed">Completed</button>
  </div>
  <ul id="list"></ul>
  <div class="info"><span id="count"></span><button id="clear">Clear completed</button></div>
</div>
<script>
const KEY='todos-v1';
let todos=[],filter='all';
try{todos=JSON.parse(localStorage.getItem(KEY))||[]}catch(e){todos=[]}
const $=id=>document.getElementById(id);
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(todos))}catch(e){}};

function render(){
  const list=$('list');
  list.innerHTML='';
  const shown=todos.filter(t=>filter==='all'||(filter==='active'?!t.done:t.done));
  if(!shown.length){
    const d=document.createElement('li');d.className='empty';d.textContent='Nothing here.';
    d.style.justifyContent='center';list.appendChild(d);
  }
  shown.forEach(t=>{
    const li=document.createElement('li');
    if(t.done)li.className='done';
    const cb=document.createElement('input');cb.type='checkbox';cb.checked=t.done;
    cb.onchange=()=>{t.done=cb.checked;save();render()};
    const sp=document.createElement('span');sp.textContent=t.text;
    const del=document.createElement('button');del.className='del';del.textContent='✕';del.title='Delete';
    del.onclick=()=>{todos=todos.filter(x=>x.id!==t.id);save();render()};
    li.append(cb,sp,del);list.appendChild(li);
  });
  const left=todos.filter(t=>!t.done).length;
  $('count').textContent=left+' item'+(left===1?'':'s')+' left';
  document.querySelectorAll('#filters button').forEach(b=>b.classList.toggle('active',b.dataset.f===filter));
}

$('form').onsubmit=e=>{
  e.preventDefault();
  const text=$('input').value.trim();
  if(!text)return;
  todos.push({id:Date.now()+Math.random(),text,done:false});
  $('input').value='';save();render();
};
$('filters').onclick=e=>{
  if(e.target.dataset.f){filter=e.target.dataset.f;render()}
};
$('clear').onclick=()=>{todos=todos.filter(t=>!t.done);save();render()};
render();
</script>
</body>
</html>
